-- RESOLVER-V3-021: developer-reviewed, server/admin-only curated knowledge. No resolver activation.
begin;
create table public.resolver_knowledge_reviews (decision_id text primary key, candidate_id text not null references public.resolver_knowledge_candidates(candidate_id), action text not null check (action in ('approve','reject','needs_more_evidence','quarantine','mark_duplicate','supersede','revoke_approval','rollback')), occurred_at timestamptz not null);
create table public.approved_resolver_knowledge (approved_knowledge_id text primary key, candidate_id text not null references public.resolver_knowledge_candidates(candidate_id), decision_id text not null unique references public.resolver_knowledge_reviews(decision_id), payload_version text not null check (payload_version = 'resolver-knowledge-review-v1'), payload jsonb not null check (jsonb_typeof(payload) = 'object'), locale text not null check (locale in ('de','en')), risk text not null check (risk in ('low','medium','high')), provenance_status text not null check (provenance_status in ('source_grounded','not_resolved')), status text not null check (status in ('active','revoked','rolled_back')), revoked_by_decision_id text references public.resolver_knowledge_reviews(decision_id), rollback_by_decision_id text references public.resolver_knowledge_reviews(decision_id));
create table public.resolver_knowledge_review_events (event_id text primary key, decision_id text not null unique references public.resolver_knowledge_reviews(decision_id), candidate_id text not null references public.resolver_knowledge_candidates(candidate_id), action text not null, result text not null, occurred_at timestamptz not null, approved_knowledge_id text references public.approved_resolver_knowledge(approved_knowledge_id));
alter table public.resolver_knowledge_reviews enable row level security; alter table public.approved_resolver_knowledge enable row level security; alter table public.resolver_knowledge_review_events enable row level security;
revoke all on table public.resolver_knowledge_reviews from anon, authenticated; revoke all on table public.approved_resolver_knowledge from anon, authenticated; revoke all on table public.resolver_knowledge_review_events from anon, authenticated;
commit;
